import sqlite3

import pytest

import sync
from feed_client import FeedError
from store import Store


@pytest.fixture
def settings(tmp_path):
    return {
        "feed": {"base_url": "http://supplier.invalid", "api_key": "test-key",
                 "page_size": 2, "timeout_seconds": 3, "max_retries": 1},
        "store": {"path": tmp_path / "catalog.db", "currency": "INR"},
        "fx_rates": {"INR": "1", "USD": "83.20", "EUR": "90.45"},
    }


def product(sku, day=1, **fields):
    return {"sku": sku, "title": "  A\t product  ", "price": "19.99",
            "currency": "usd", "updated_at": f"2026-11-{day:02d}T00:00:00Z",
            **fields}


def tombstone(sku, day):
    return {"sku": sku, "deleted": True,
            "updated_at": f"2026-11-{day:02d}T00:00:00Z"}


def fake_feed(monkeypatch, pages):
    calls = []
    options = []

    class Client:
        def __init__(self, *args, **kwargs):
            options.append((args, kwargs))

        def fetch_page(self, cursor=None):
            calls.append(cursor)
            result = pages[cursor]
            if isinstance(result, Exception):
                raise result
            return result

    monkeypatch.setattr(sync, "FeedClient", Client)
    return calls, options


def page(items, cursor=None):
    return {"data": {"items": items}, "next_cursor": cursor}


def snapshot(path):
    with sqlite3.connect(path) as conn:
        return "\n".join(conn.iterdump())


def test_sync_pages_ordering_normalization_and_rerun(monkeypatch, settings):
    calls, options = fake_feed(monkeypatch, {
        None: page([product("A", 3), product("B"), tombstone("C", 3),
                    tombstone("D", 2)], "opaque+/= cursor"),
        "opaque+/= cursor": page([
            product("A", 2, price="1"), tombstone("B", 2), product("B"),
            product("C", 2), product("D", 3, currency="EUR", price="4.5"),
            product("bad-price", price="call for price"),
            product("bad-currency", currency="JPY"),
        ]),
    })
    report = sync.run_sync(settings)
    assert report == sync.SyncReport(pages=2, upserted=3, deleted=1,
                                     skipped=2, unchanged=5)
    assert calls == [None, "opaque+/= cursor"]
    assert options[0] == (("http://supplier.invalid", "test-key"),
                          {"page_size": 2, "timeout": 3, "max_retries": 1})
    with Store(settings["store"]["path"]) as store:
        assert [row["sku"] for row in store.all_products()] == ["A", "D"]
        assert store.get("A") == {
            "sku": "A", "title": "A product", "price_minor": 166317,
            "currency": "INR", "stock": 0, "updated_at": "2026-11-03T00:00:00Z",
        }
        assert store.get("D")["price_minor"] == 40703
    before = snapshot(settings["store"]["path"])
    again = sync.run_sync(settings)
    assert again == sync.SyncReport(pages=2, skipped=2, unchanged=9)
    assert snapshot(settings["store"]["path"]) == before


def test_feed_failure_rolls_back_all_pages(monkeypatch, settings):
    with Store(settings["store"]["path"]) as store:
        store.upsert(sync.normalize_item(product("existing"),
                                        sync.load_rates(settings["fx_rates"]), "INR"))
    before = snapshot(settings["store"]["path"])
    fake_feed(monkeypatch, {
        None: page([product("new"), tombstone("existing", 2)], "next"),
        "next": FeedError("unavailable"),
    })
    with pytest.raises(FeedError, match="unavailable"):
        sync.run_sync(settings)
    assert snapshot(settings["store"]["path"]) == before


def test_empty_page_does_not_end_pagination(monkeypatch, settings):
    fake_feed(monkeypatch, {None: page([], "next"), "next": page([product("A")])})
    assert sync.run_sync(settings) == sync.SyncReport(pages=2, upserted=1)


def test_repeated_cursor_rolls_back(monkeypatch, settings):
    fake_feed(monkeypatch, {None: page([product("A")], "loop"),
                           "loop": page([], "loop")})
    with pytest.raises(FeedError, match="repeated"):
        sync.run_sync(settings)
